.wssurv__h2{font-size:clamp(24px,3vw,36px);font-weight:800;line-height:1.2;margin:0 0 16px;color:inherit}.wssurv__h2 em{font-style:italic;color:#e2601a}
.wssurv__h3{font-size:22px;font-weight:800;margin:0 0 10px;display:flex;align-items:center;gap:12px}
.wssurv__p{font-size:15.5px;line-height:1.65;margin:0 0 14px;color:#333}.wssurv__s--bg2 .wssurv__p{color:#d9d3ca}
.wssurv__zak{font-size:16px;font-weight:800;line-height:1.5;margin:18px 0 0}
.wssurv__dva{display:grid;grid-template-columns:1fr 1.05fr;gap:48px;align-items:center}.wssurv__dva--rev>div:first-child{order:2}
.wssurv__media{border-radius:16px;overflow:hidden;box-shadow:0 14px 34px rgba(0,0,0,.14);aspect-ratio:4/5}.wssurv__media--kv{aspect-ratio:1/1}
.wssurv__media img,.wssurv__media video{width:100%;height:100%;object-fit:cover;display:block}
.wssurv__karw{position:relative}.wssurv__kar{display:grid;grid-auto-flow:column;grid-auto-columns:calc((100% - 40px)/3);gap:20px;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none;margin-top:24px}.wssurv__kar::-webkit-scrollbar{display:none}
.wssurv__vk{scroll-snap-align:start;position:relative;border-radius:16px;overflow:hidden;box-shadow:0 10px 26px rgba(0,0,0,.14);background:#000}.wssurv__vk video{width:100%;aspect-ratio:2/3;object-fit:cover;display:block}
.wssurv__vt{position:absolute;left:12px;right:12px;bottom:12px;background:rgba(255,255,255,.94);border-radius:12px;padding:10px 12px;font-size:14px;font-weight:700;line-height:1.35;color:#1c1c1c}
.wssurv__pus{position:absolute;top:50%;transform:translateY(-50%);width:44px;height:44px;border-radius:50%;border:0;background:#fff;box-shadow:0 4px 14px rgba(0,0,0,.18);font-size:24px;line-height:44px;cursor:pointer;z-index:2;color:#e2601a;padding:0}.wssurv__pus--l{left:-14px}.wssurv__pus--d{right:-14px}
.wssurv__tabs{display:flex;flex-wrap:wrap;gap:8px;margin:4px 0 16px}.wssurv__tab{width:42px;height:42px;border-radius:50%;border:0;background:#fdf0e7;color:#e2601a;font-weight:800;font-size:16px;cursor:pointer;transition:background .2s,color .2s}.wssurv__tab.is-on,.wssurv__tab:hover{background:#e2601a;color:#fff}
.wssurv__dio{display:none;background:#fff;border-radius:16px;padding:24px;box-shadow:0 8px 24px rgba(226,96,26,.12)}.wssurv__dio.is-on{display:block}
.wssurv__br{flex:0 0 40px;width:40px;height:40px;border-radius:50%;background:#e2601a;color:#fff;font-weight:800;font-size:15px;display:inline-flex;align-items:center;justify-content:center;box-shadow:0 4px 12px rgba(226,96,26,.35)}
.wssurv__chips{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:6px}.wssurv__chips div{background:#fdf0e7;border-radius:12px;padding:12px 8px;text-align:center}.wssurv__chips strong{display:block;font-size:16px;color:#e2601a;font-weight:800}.wssurv__chips span{display:block;font-size:13px;color:#555;margin-top:2px}
.wssurv__stat{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin:18px 0 14px}.wssurv__stat div{background:rgba(255,255,255,.06);border-radius:14px;padding:16px;box-shadow:inset 0 0 0 1px rgba(239,106,31,.35)}.wssurv__stat strong{display:block;font-size:22px;font-weight:800;color:#ef6a1f}.wssurv__stat span{display:block;font-size:13.5px;color:#d9d3ca;margin-top:2px}
.wssurv__nema{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-top:36px}.wssurv__nema span{display:flex;align-items:center;justify-content:center;gap:10px;background:#ef6a1f;color:#fff;border-radius:30px;padding:12px 16px;font-size:15px;font-weight:700}.wssurv__nema svg{width:20px;height:20px;flex:0 0 20px}
.wssurv__sus{display:grid;grid-template-columns:1fr minmax(0,400px) 1fr;gap:40px;align-items:center;margin-top:30px}.wssurv__smid{width:100%}
.wssurv__sst{display:flex;flex-direction:column;gap:18px}.wssurv__sst>div{background:rgba(255,255,255,.06);border-radius:16px;padding:22px 20px;box-shadow:inset 0 0 0 1px rgba(239,106,31,.35);text-align:center}.wssurv__sst strong{display:block;font-size:clamp(20px,2.2vw,26px);font-weight:800;color:#ef6a1f;white-space:nowrap;line-height:1.2}.wssurv__sst>div>span:last-child{display:block;font-size:14px;color:#d9d3ca;margin-top:4px}
span.wssurv__si{width:48px;height:48px;border-radius:50%;background:rgba(239,106,31,.16);color:#ef6a1f;display:flex;align-items:center;justify-content:center;margin:0 auto 10px}
.wssurv__grid{display:grid;gap:20px;margin-top:24px}.wssurv__g4{grid-template-columns:repeat(4,1fr)}
.wssurv__k{background:#fff;border-radius:16px;overflow:hidden;display:flex;flex-direction:column;box-shadow:0 8px 24px rgba(0,0,0,.08);transition:transform .2s,box-shadow .2s}.wssurv__k:hover{transform:translateY(-3px);box-shadow:0 14px 30px rgba(226,96,26,.20)}
.wssurv__km{position:relative}.wssurv__km img{width:100%;aspect-ratio:3/4;object-fit:cover;display:block}.wssurv__km .wssurv__br{position:absolute;left:12px;top:12px}
.wssurv__kt{padding:18px 18px 22px}.wssurv__kt strong{display:block;font-size:17px;margin-bottom:6px;font-weight:800}.wssurv__kt p{margin:0;font-size:14.5px;line-height:1.6;color:#333}
.wssurv__tmreza{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-top:28px}.wssurv__tk{display:flex;align-items:center;gap:14px;background:#fdf0e7;border-radius:16px;padding:18px}.wssurv__ti{flex:0 0 50px;width:50px;height:50px;border-radius:50%;background:linear-gradient(135deg,#e2601a,#f08a4b);color:#fff;display:flex;align-items:center;justify-content:center}.wssurv__tt strong{display:block;font-size:15.5px;font-weight:800}.wssurv__tt span{display:block;font-size:13px;color:#5a5f6b;margin-top:2px}
.wssurv__red4{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;text-align:center;margin-top:22px}.wssurv__pog>div{background:#fff;border-radius:16px;box-shadow:0 6px 20px rgba(0,0,0,.07);padding:26px 16px}.wssurv__pog strong{display:block;font-size:17px;font-weight:800}.wssurv__pog span{display:block;font-size:13.5px;color:#555}
span.wssurv__pi{width:56px;height:56px;border-radius:50%;background:#fbe0cf;color:#e2601a;display:flex;align-items:center;justify-content:center;margin:0 auto 12px}
@media (max-width:860px){.wssurv__s{padding:46px 0}.wssurv__dva{grid-template-columns:1fr;gap:24px}.wssurv__dva--rev>div:first-child{order:0}.wssurv__kar{grid-auto-columns:calc((100% - 14px)/2);gap:14px}.wssurv__pus--l{left:4px}.wssurv__pus--d{right:4px}.wssurv__g4,.wssurv__tmreza,.wssurv__red4{grid-template-columns:1fr 1fr}.wssurv__chips{grid-template-columns:1fr 1fr}.wssurv__tk{flex-direction:column;text-align:center;padding:14px 10px}.wssurv__vt{font-size:13px;padding:8px 10px}.wssurv__sus{grid-template-columns:1fr 1fr;gap:14px}.wssurv__smid{grid-column:1/-1;order:-1;max-width:420px;margin:0 auto}.wssurv__sst{gap:14px}.wssurv__sst>div{padding:16px 10px}.wssurv__nema{grid-template-columns:1fr 1fr;gap:10px;margin-top:22px}.wssurv__nema span{font-size:14px;padding:10px 10px}}
@media (max-width:560px){.wssurv__g4{grid-template-columns:1fr}}
@media (max-width:400px){.wssurv__sst strong{font-size:18px}}
@media (max-width:767px){.wssurv__v{padding:0 16px}}
</style>
<script>
(function(){var r=document.querySelector('.wssurv');if(!r)return;
r.querySelectorAll('.wssurv__tab').forEach(function(b){b.addEventListener('click',function(){var i=b.getAttribute('data-i');
r.querySelectorAll('.wssurv__tab').forEach(function(x){x.classList.toggle('is-on',x===b);});
r.querySelectorAll('.wssurv__dio').forEach(function(x){x.classList.toggle('is-on',x.getAttribute('data-i')===i);});});});
r.querySelectorAll('.wssurv__kar').forEach(function(k){var w=document.createElement('div');w.className='wssurv__karw';k.parentNode.insertBefore(w,k);w.appendChild(k);
['l','d'].forEach(function(s){var b=document.createElement('button');b.type='button';b.className='wssurv__pus wssurv__pus--'+s;b.setAttribute('aria-label',s==='l'?'Prethodno':'Sljedeće');b.innerHTML=s==='l'?'&#8249;':'&#8250;';
b.addEventListener('click',function(){var x=k.firstElementChild;var d=x?x.getBoundingClientRect().width+20:300;k.scrollBy({left:s==='l'?-d:d,behavior:'smooth'});});w.appendChild(b);});});
})();
</script>
